def _strip_prefix(path: str | None) -> str | None:
    if path is None:
        return None
    if path.startswith(("a/", "b/")):
        return path[2:]
    return path

def to_hunk_only_patch(patch_str: str) -> str:
    """Drop file-header lines ('diff --git', 'index', '---', '+++') that precede
    the first '@@' hunk header.

    Platform providers (GitHub, GitLab, ...) store hunk-only patches, and the
    shared hunk/line-number converter treats any '+'/'-' line as content. Left
    in, the '---'/'+++' headers would be emitted as a bogus leading hunk with
    invalid line numbers. Returns "" when there is no hunk (e.g. rename-only)."""
    lines = patch_str.splitlines(keepends=True)
    for i, line in enumerate(lines):
        if line.startswith("@@"):
            return "".join(lines[i:])
    return ""

def _call(*command, **kwargs) -> (int, str, str):
    res = subprocess.run(
        command,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        check=True,
        **kwargs,
    )
    return res.stdout.decode()

def show(*args, cwd=None):
    get_logger().info("Show")
    return _call('git', 'show', *args, cwd=cwd)

def reset_local_changes(cwd):
    get_logger().info("Reset local changes")
    _call('git', 'checkout', "--force", cwd=cwd)

def upload_patch(patch, path):
    patch_server_endpoint = get_settings().get(
        'gerrit.patch_server_endpoint')
    patch_server_token = get_settings().get(
        'gerrit.patch_server_token')

    response = requests.post(
        patch_server_endpoint,
        json={
            "content": patch,
            "path": path,
        },
        headers={
            "Content-Type": "application/json",
            "Authorization": f"Bearer {patch_server_token}",
        }
    )
    response.raise_for_status()
    patch_server_endpoint = patch_server_endpoint.rstrip("/")
    return patch_server_endpoint + "/" + path

